const input = $input.first().json;
const prevData = $('Parse Claude').first().json;

if (input.error) {
  // GPT failed, use Claude result as-is
  return [{
    json: {
      ...prevData,
      gpt_validation: { valid: true, score: 0.7, note: 'GPT validation skipped' },
      final_metadata: prevData.claude_result,
      status: 'gpt_skipped'
    }
  }];
}

try {
  const content = input.choices?.[0]?.message?.content;
  const validation = JSON.parse(content);

  // Apply corrections if any
  let finalMetadata = prevData.claude_result;
  if (validation.corrections) {
    finalMetadata = { ...prevData.claude_result, ...validation.corrections };
  }

  return [{
    json: {
      ...prevData,
      gpt_validation: validation,
      final_metadata: finalMetadata,
      status: validation.valid ? 'validated' : 'corrected'
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      gpt_validation: { valid: true, score: 0.7, note: 'Parse error, using Claude' },
      final_metadata: prevData.claude_result,
      status: 'gpt_parse_error'
    }
  }];
}

const input = $input.first().json;
const prevData = $('Parse GPT').first().json;

// Use workflow_id directly as point_id (Qdrant accepts string IDs)
function workflowToPointId(workflowId) {
  // Convert workflow_id to a valid UUID using a simple deterministic method
  // Pad the workflow_id and convert to hex-like format
  const padded = (workflowId + '0000000000000000').substring(0, 16);
  let hex = '';
  for (let i = 0; i < padded.length; i++) {
    hex += padded.charCodeAt(i).toString(16).padStart(2, '0');
  }
  // Format: 8-4-4-4-12 (total 32 hex chars)
  return `${hex.substring(0,8)}-${hex.substring(8,12)}-4${hex.substring(12,15)}-a${hex.substring(15,18)}-${hex.substring(18,30)}`;
}

const embedding = input.data?.[0]?.embedding;

if (!embedding) {
  return [{
    json: {
      ...prevData,
      embedding: null,
      embedding_error: 'No embedding generated',
      status: 'embedding_failed'
    }
  }];
}

// Deterministic point_id based on workflow_id
const pointId = workflowToPointId(prevData.workflow_id);

// Build Qdrant payload
const payload = {
  workflow_id: prevData.workflow_id,
  webhook_path: prevData.webhook_path,
  webhook_url: `http://pi6.local:5678/webhook/${prevData.webhook_path}`,
  webhook_method: prevData.webhook_method,
  name: prevData.name,
  description: prevData.final_metadata.description,
  category: prevData.final_metadata.category,
  keywords: prevData.final_metadata.keywords,
  use_cases: prevData.final_metadata.use_cases,
  operations: prevData.final_metadata.operations,
  enrichment_score: prevData.gpt_validation?.score || 0.7,
  enriched_at: new Date().toISOString(),
  enricher_version: '1.0',
  source_updated_at: prevData.updated_at,
  active: true,
  scope: 'user'
};

console.log(`[Enricher] Preparing: ${prevData.name} (${prevData.workflow_id})`);

return [{
  json: {
    ...prevData,
    embedding,
    point_id: pointId,
    qdrant_payload: payload,
    status: 'ready_to_store'
  }
}];

const input = $input.first().json;
const prevData = $('Prepare Qdrant').first().json;
const config = $('Validate Input').first().json.config;

let status = 'enriched';
if (config.dryRun) {
  status = 'dry_run';
} else if (input.error) {
  status = 'qdrant_failed';
}

const result = {
  workflow_id: prevData.workflow_id,
  name: prevData.name,
  webhook_path: prevData.webhook_path,
  status,
  enrichment_score: prevData.gpt_validation?.score || 0.7,
  point_id: prevData.point_id,
  timestamp: new Date().toISOString(),
  error: input.error?.message || null
};

// Log progress
const staticData = $getWorkflowStaticData('global');
staticData.results.push(result);
const count = staticData.results.length;
console.log(`[Enricher] ${count}. ${status.toUpperCase()}: ${prevData.name}`);

return [{ json: result }];

const prevData = $input.first().json;

const result = {
  workflow_id: prevData.workflow_id,
  name: prevData.name,
  webhook_path: prevData.webhook_path,
  status: 'failed',
  error: prevData.claude_error || 'Unknown error',
  timestamp: new Date().toISOString()
};

// Log failure
const staticData = $getWorkflowStaticData('global');
staticData.results.push(result);
const count = staticData.results.length;
console.log(`[Enricher] ${count}. FAILED: ${prevData.name} - ${result.error}`);

return [{ json: result }];

const config = $('Validate Input').first().json.config;
const staticData = $getWorkflowStaticData('global');
const results = staticData.results || [];
const startedAt = staticData.startedAt;

// Calculate stats
const enriched = results.filter(r => r.status === 'enriched').length;
const dryRunCount = results.filter(r => r.status === 'dry_run').length;
const failed = results.filter(r => r.status === 'failed' || r.status === 'qdrant_failed').length;
const errors = results.filter(r => r.status === 'failed' || r.status === 'qdrant_failed');

const stats = {
  job_id: staticData.jobId,
  mode: config.mode,
  dry_run: config.dryRun,
  total: results.length,
  enriched,
  dry_run_count: dryRunCount,
  failed,
  duration_ms: Date.now() - new Date(startedAt).getTime(),
  collection: config.qdrantCollection
};

return [{
  json: {
    success: failed === 0,
    message: failed === 0 
      ? `Enrichment completed: ${enriched} tools indexed.` 
      : `Enrichment completed with ${failed} errors.`,
    stats,
    errors: errors.length > 0 ? errors : null,
    results: results
  }
}];
